#include <iostream>
#include <algorithm>
#include <utility>
using namespace std;

long long cube(long long c) {
    return c * c * c;
}

long long getBiggestCube(long long m) {
    int l = 1, r = 100010;
    int ans = -1;

    while (l <= r) {
        int mid = l + (r - l) / 2;
        long long value = cube(mid);

        if (value == m) {
            ans = mid;
            break;
        }

        if (value > m) {
            r = mid - 1;
        } else {
            ans = mid;
            l = mid + 1;
        }
    }

    return ans;
}

pair<int, long long> getAns(long long m) {
    if (m == 0) {
        return {0, 0};
    }

    long long c = getBiggestCube(m);
    pair<int, long long> p1 = getAns(m - cube(c));
    pair<int, long long> p2 = getAns(cube(c) - 1 - cube(c - 1));

    pair<int, long long> ans1 = {p1.first + 1, p1.second + cube(c)};
    pair<int, long long> ans2 = {p2.first + 1, p2.second + cube(c - 1)};

    if (ans1.first != ans2.first) {
        return ans1.first > ans2.first ? ans1 : ans2;
    }

    return ans1.second > ans2.second ? ans1 : ans2;
}

int main() {
    long long m;
    cin >> m;

    pair<int, long long> ans = getAns(m);
    cout << ans.first << ' ' << ans.second << '\n';

    return 0;
}

